<?php
namespace App\Http\Controllers;
use App\Models\{Customer,Event,EventRegistration};use App\Http\Requests\StoreEventRegistrationRequest;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class EventRegistrationController extends Controller { public function store(StoreEventRegistrationRequest $request,Event $event){$d=$request->validated();DB::transaction(function()use($d,$event){$locked=Event::whereKey($event->id)->lockForUpdate()->firstOrFail();if($locked->status!=='buka')throw ValidationException::withMessages(['email'=>'Pendaftaran untuk event ini sudah ditutup.']);$customer=Customer::firstOrCreate(['email'=>$d['email']],['name'=>$d['name'],'phone'=>$d['phone'],'organization'=>$d['organization']??null,'segment'=>'umum']);if(EventRegistration::where('event_id',$locked->id)->where('customer_id',$customer->id)->exists())throw ValidationException::withMessages(['email'=>'Email ini sudah terdaftar pada event tersebut.']);if($locked->remaining_quota<1){$locked->update(['status'=>'penuh']);throw ValidationException::withMessages(['email'=>'Kuota event sudah penuh.']);}EventRegistration::create(['event_id'=>$locked->id,'customer_id'=>$customer->id,'registered_at'=>now()]);if($locked->remaining_quota<1)$locked->update(['status'=>'penuh']);});return back()->with('success','Pendaftaran berhasil! Sampai jumpa di acara TechMoon.');} }
